{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2139-02-05 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning, Mr. ___. I'm Dr. ___, one of the internal medicine doctors looking after you. You were just brought up from the procedure suite after your bronchoscopy and balloon dilation. How are you feeling?"
    },
    {
      "turn_number": 2,
      "time": "2139-02-05 08:02:00",
      "speaker": "Patient",
      "text": "Hey doc. Throat hurts... kind of sore around the trach. But I’m okay, I guess."
    },
    {
      "turn_number": 3,
      "time": "2139-02-05 08:03:00",
      "speaker": "Doctor",
      "text": "That makes sense. You had a procedure today to open up some narrowing in your airway, so some soreness is expected. We’ll manage your pain carefully. Any trouble breathing?"
    },
    {
      "turn_number": 4,
      "time": "2139-02-05 08:04:00",
      "speaker": "Patient",
      "text": "No, breathing’s about the same. Still wheezing a bit, but that’s normal for me."
    },
    {
      "turn_number": 5,
      "time": "2139-02-05 08:05:00",
      "speaker": "Doctor",
      "text": "Yes, your lungs have been doing that for a while. The team said the procedure went smoothly—no complications. You’ll stay with us for a few days to control the pain and make sure everything stays stable."
    },
    {
      "turn_number": 6,
      "time": "2139-02-05 08:06:00",
      "speaker": "Patient",
      "text": "Okay. I’ve done this before. Just want to get back home soon."
    },
    {
      "turn_number": 7,
      "time": "2139-02-05 08:07:00",
      "speaker": "Doctor",
      "text": "We’ll work toward that. For now, you’ll get acetaminophen every 8 hours and ibuprofen every 6 hours as needed. Oxycodone is available for breakthrough pain—just let the nurse know."
    },
    {
      "turn_number": 8,
      "time": "2139-02-05 08:08:00",
      "speaker": "Patient",
      "text": "I don’t like taking too much of that oxycodone. Makes me foggy."
    },
    {
      "turn_number": 9,
      "time": "2139-02-05 08:09:00",
      "speaker": "Doctor",
      "text": "Totally understandable. We’ll use it only when needed and taper it as your pain improves. Most patients stop it within a day or two."
    },
    {
      "turn_number": 10,
      "time": "2139-02-05 08:10:00",
      "speaker": "Patient",
      "text": "Good. And I need my oxygen at night, right?"
    },
    {
      "turn_number": 11,
      "time": "2139-02-05 08:11:00",
      "speaker": "Doctor",
      "text": "Yes, you’re on your usual home oxygen regimen through the trach. We’re monitoring your oxygen levels, and they’re good—96% on room air."
    },
    {
      "turn_number": 12,
      "time": "2139-02-05 10:30:00",
      "speaker": "Doctor",
      "text": "Hi again. I just reviewed your labs. Your white blood cell count is a bit high—18.0—probably from the procedure or mild inflammation. Nothing suggests infection."
    },
    {
      "turn_number": 13,
      "time": "2139-02-05 10:31:00",
      "speaker": "Patient",
      "text": "Is that bad? Should I be worried?"
    },
    {
      "turn_number": 14,
      "time": "2139-02-05 10:32:00",
      "speaker": "Doctor",
      "text": "Not at all. It’s common after procedures like this. We’ll watch it, and it should come down in a day or two."
    },
    {
      "turn_number": 15,
      "time": "2139-02-05 14:00:00",
      "speaker": "Patient",
      "text": "Doc, can I sit up more? I feel okay, just a little sore."
    },
    {
      "turn_number": 16,
      "time": "2139-02-05 14:01:00",
      "speaker": "Doctor",
      "text": "Of course. You’re stable. We encourage moving around as tolerated. Just call for help if you feel dizzy or short of breath."
    },
    {
      "turn_number": 17,
      "time": "2139-02-06 07:00:00",
      "speaker": "Doctor",
      "text": "Good morning. Your pain still the main issue?"
    },
    {
      "turn_number": 18,
      "time": "2139-02-06 07:01:00",
      "speaker": "Patient",
      "text": "Yeah, throat’s still sore. Took ibuprofen last night, helped a bit."
    },
    {
      "turn_number": 19,
      "time": "2139-02-06 07:02:00",
      "speaker": "Doctor",
      "text": "We’ll keep that up. Your breathing sounds are still wheezy, but no new concerns. We’re continuing your prednisone as usual."
    },
    {
      "turn_number": 20,
      "time": "2139-02-06 07:03:00",
      "speaker": "Patient",
      "text": "What about my pirfenidone? I haven’t been taking it—ran out."
    },
    {
      "turn_number": 21,
      "time": "2139-02-06 07:04:00",
      "speaker": "Doctor",
      "text": "It’s not available here due to formulary rules, but the interventional pulmonology team will help you get it set up as an outpatient. It’s not urgent to restart right now."
    },
    {
      "turn_number": 22,
      "time": "2139-02-06 07:05:00",
      "speaker": "Patient",
      "text": "Okay, good. I just didn’t want it forgotten."
    },
    {
      "turn_number": 23,
      "time": "2139-02-06 07:06:00",
      "speaker": "Doctor",
      "text": "We’ll make sure it’s coordinated before you go home."
    },
    {
      "turn_number": 24,
      "time": "2139-02-06 15:00:00",
      "speaker": "Doctor",
      "text": "Your repeat labs are back. White count dropped to 9.4—much better. Hemoglobin is stable. This is a good sign."
    },
    {
      "turn_number": 25,
      "time": "2139-02-06 15:01:00",
      "speaker": "Patient",
      "text": "So I’m healing?"
    },
    {
      "turn_number": 26,
      "time": "2139-02-06 15:02:00",
      "speaker": "Doctor",
      "text": "Yes, exactly. Your body is recovering as expected. Pain should keep improving."
    },
    {
      "turn_number": 27,
      "time": "2139-02-07 08:00:00",
      "speaker": "Doctor",
      "text": "Morning. How’s the pain today—better?"
    },
    {
      "turn_number": 28,
      "time": "2139-02-07 08:01:00",
      "speaker": "Patient",
      "text": "Yeah, much better. Didn’t need any oxycodone last night."
    },
    {
      "turn_number": 29,
      "time": "2139-02-07 08:02:00",
      "speaker": "Doctor",
      "text": "That’s great. We’ll stop the oxycodone and keep you on acetaminophen and ibuprofen as needed. You’re right on track."
    },
    {
      "turn_number": 30,
      "time": "2139-02-07 08:03:00",
      "speaker": "Patient",
      "text": "Can I go home soon?"
    },
    {
      "turn_number": 31,
      "time": "2139-02-07 08:04:00",
      "speaker": "Doctor",
      "text": "Possibly by tomorrow or the day after. We want to make sure your pain is well-controlled without opioids and that you’re stable."
    },
    {
      "turn_number": 32,
      "time": "2139-02-07 10:00:00",
      "speaker": "Patient",
      "text": "The biopsy—what did it show?"
    },
    {
      "turn_number": 33,
      "time": "2139-02-07 10:01:00",
      "speaker": "Doctor",
      "text": "Good question. The tissue from your airway showed squamous metaplasia and mild chronic inflammation. No infection or cancer. It’s consistent with your long-term airway changes."
    },
    {
      "turn_number": 34,
      "time": "2139-02-07 10:02:00",
      "speaker": "Patient",
      "text": "So nothing serious?"
    },
    {
      "turn_number": 35,
      "time": "2139-02-07 10:03:00",
      "speaker": "Doctor",
      "text": "Nothing urgent or dangerous. It explains the narrowing and why you need these procedures."
    },
    {
      "turn_number": 36,
      "time": "2139-02-08 07:30:00",
      "speaker": "Doctor",
      "text": "Hi. Vital signs are excellent—heart rate 81, blood pressure 133/80, oxygen 98% on trach mask. Lungs sound much clearer."
    },
    {
      "turn_number": 37,
      "time": "2139-02-08 07:31:00",
      "speaker": "Patient",
      "text": "I feel good. Ready to go home."
    },
    {
      "turn_number": 38,
      "time": "2139-02-08 07:32:00",
      "speaker": "Doctor",
      "text": "We’re planning for discharge tomorrow. We’ll confirm the plan with your pulmonologist, and the team will help set up your follow-up and medications."
    },
    {
      "turn_number": 39,
      "time": "2139-02-08 07:33:00",
      "speaker": "Patient",
      "text": "Will I need another dilation soon?"
    },
    {
      "turn_number": 40,
      "time": "2139-02-08 07:34:00",
      "speaker": "Doctor",
      "text": "That’s up to your pulmonologist, but these are usually scheduled every few months based on symptoms. You’ll have a follow-up appointment to discuss that."
    },
    {
      "turn_number": 41,
      "time": "2139-02-08 13:00:00",
      "speaker": "Doctor",
      "text": "The discharge order is in. You’ll go home tomorrow morning if all stays well tonight."
    },
    {
      "turn_number": 42,
      "time": "2139-02-08 13:01:00",
      "speaker": "Patient",
      "text": "Great. What about my trach? It feels okay, but I want to make sure I’m taking care of it right."
    },
    {
      "turn_number": 43,
      "time": "2139-02-08 13:02:00",
      "speaker": "Doctor",
      "text": "Good point. The nurse will review trach care with you—cleaning, suctioning, and signs of infection or blockage. You’ve done this before, but a refresher helps."
    },
    {
      "turn_number": 44,
      "time": "2139-02-08 13:03:00",
      "speaker": "Patient",
      "text": "And if it starts hurting again?"
    },
    {
      "turn_number": 45,
      "time": "2139-02-08 13:04:00",
      "speaker": "Doctor",
      "text": "Use the acetaminophen and ibuprofen as prescribed. If pain worsens or you develop fever or breathing trouble, call your doctor or go to the ER."
    },
    {
      "turn_number": 46,
      "time": "2139-02-09 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. You’re officially ready for discharge. We’ve arranged your follow-up with pulmonology and helped start the process for your pirfenidone prescription."
    },
    {
      "turn_number": 47,
      "time": "2139-02-09 08:01:00",
      "speaker": "Patient",
      "text": "Thanks, doc. I feel a lot better."
    },
    {
      "turn_number": 48,
      "time": "2139-02-09 08:02:00",
      "speaker": "Doctor",
      "text": "You did well. Continue the home meds, including prednisone as directed. Watch for any breathing changes or signs of infection."
    },
    {
      "turn_number": 49,
      "time": "2139-02-09 08:03:00",
      "speaker": "Patient",
      "text": "I will. And I’ll keep using oxygen at night."
    },
    {
      "turn_number": 50,
      "time": "2139-02-09 08:04:00",
      "speaker": "Doctor",
      "text": "Perfect. You’re all set. The nurse will go over your discharge papers and answer any last questions."
    },
    {
      "turn_number": 51,
      "time": "2139-02-09 08:05:00",
      "speaker": "Patient",
      "text": "Appreciate it. Everyone’s been great."
    },
    {
      "turn_number": 52,
      "time": "2139-02-09 08:06:00",
      "speaker": "Doctor",
      "text": "Glad to hear it. Take care, and see you in follow-up."
    },
    {
      "turn_number": 53,
      "time": "2139-02-09 10:00:00",
      "speaker": "Patient",
      "text": "Just wanted to say thanks again before I leave."
    },
    {
      "turn_number": 54,
      "time": "2139-02-09 10:01:00",
      "speaker": "Doctor",
      "text": "You’re very welcome. Stay well, and don’t hesitate to reach out if anything changes."
    },
    {
      "turn_number": 55,
      "time": "2139-02-09 10:02:00",
      "speaker": "Patient",
      "text": "Will do."
    },
    {
      "turn_number": 56,
      "time": "2139-02-09 12:00:00",
      "speaker": "Doctor",
      "text": "Final check-in—still feeling good?"
    },
    {
      "turn_number": 57,
      "time": "2139-02-09 12:01:00",
      "speaker": "Patient",
      "text": "Yes, no pain, breathing fine."
    },
    {
      "turn_number": 58,
      "time": "2139-02-09 12:02:00",
      "speaker": "Doctor",
      "text": "Excellent. Discharge is confirmed for this afternoon."
    },
    {
      "turn_number": 59,
      "time": "2139-02-09 14:00:00",
      "speaker": "Patient",
      "text": "Nurse said I can leave soon. Just waiting on the ride."
    },
    {
      "turn_number": 60,
      "time": "2139-02-09 14:01:00",
      "speaker": "Doctor",
      "text": "Perfect. I’ll stop by one last time to say goodbye before you go."
    },
    {
      "turn_number": 61,
      "time": "2139-02-09 15:00:00",
      "speaker": "Doctor",
      "text": "All set. You’re discharged. Take it easy, follow up as scheduled, and keep managing your symptoms."
    },
    {
      "turn_number": 62,
      "time": "2139-02-09 15:01:00",
      "speaker": "Patient",
      "text": "Thanks again, doc. Really appreciate it."
    },
    {
      "turn_number": 63,
      "time": "2139-02-09 15:02:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Stay safe and well."
    },
    {
      "turn_number": 64,
      "time": "2139-02-09 15:30:00",
      "speaker": "Patient",
      "text": "Just letting you know—I’m about to head out."
    },
    {
      "turn_number": 65,
      "time": "2139-02-09 15:31:00",
      "speaker": "Doctor",
      "text": "Got it. Have a smooth recovery at home."
    },
    {
      "turn_number": 66,
      "time": "2139-02-09 15:32:00",
      "speaker": "Patient",
      "text": "Will do."
    },
    {
      "turn_number": 67,
      "time": "2139-02-09 15:33:00",
      "speaker": "Doctor",
      "text": "Take care, Mr. ___. See you in clinic."
    }
  ],
  "summary": {
    "admission_start": "2139-02-05 08:00:00",
    "admission_end": "2139-02-09 16:57:00",
    "summary_paragraph": "Mr. ___ was admitted for post-procedural pain management following a scheduled flexible bronchoscopy with balloon dilation of the trachea and excision of friable mucosa, due to recurrent tracheal stenosis from Ruvalcaba-Myhre-Smith syndrome and relapsing polychondritis. The procedure was uncomplicated, and he was monitored on the internal medicine service. His pain was managed with acetaminophen, ibuprofen, and short-term oxycodone, with successful weaning off opioids by discharge. His white blood cell count, initially elevated, normalized during the stay. Biopsy of the excised tissue showed squamous metaplasia and mild chronic inflammation without malignancy. Home prednisone was continued, and plans were made to restart pirfenidone as an outpatient. He remained stable, with improved respiratory symptoms and pain control, and was discharged home in good condition with follow-up arranged.",
    "problems": [
      "Malfunction of tracheostomy stoma",
      "Chronic respiratory failure with hypoxia",
      "Other acute postprocedural pain",
      "Other intellectual disabilities",
      "Relapsing polychondritis",
      "Gastro-esophageal reflux disease without esophagitis",
      "Essential (primary) hypertension"
    ]
  }
}
